int factoryCount() { return 112; }
const Patch& factoryPatch(int i) {
    static std::vector<Patch> cache;
    if (cache.empty()) {
        for (const FRow& r : kRows) {
            Patch p; p.name = r.name; p.type = r.type;
            std::string g = r.genres; size_t a = 0;
            while (a <= g.size() && !g.empty()) { size_t b = g.find('|', a); if (b == std::string::npos) b = g.size(); p.genres.push_back(g.substr(a, b - a)); a = b + 1; }
            for (int k = 0; k < r.n; ++k) p.v[kVals[r.start + k].idx] = kVals[r.start + k].value;
            p.clampAll(); cache.push_back(p);
        }
    }
    return cache[(size_t) i];
}
